contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address caller,
        uint256 artId,
        uint256 tokenId,
        uint256 quantity,
        address to,
        address from,
        uint256[] memory ids,
        uint256[] memory values,
        bytes memory data,
        string memory imageURI,
        bytes32 dataHash,
        uint256 _artFee
    )
        public
        payable
    {
        require(address(this).balance >= _artFee, "insufficient balance for art fee");
        require(caller != address(0), "caller zero address");

        address ownerBefore = c.owner();
        uint256 tokenIdCounterBefore = c.tokenIdCounter();
        uint256 credIdBefore = c.credId();
        uint256 credChainIdBefore = c.credChainId();
        address phiFactoryBefore = address(c.phiFactoryContract());
        address protocolFeeBefore = c.protocolFeeDestination();
        bool pausedBefore = c.paused();

        // Try a factory-only function: createArtFromFactory
        (bool successCreate, bytes memory retCreate) = address(c).call(
            abi.encodeWithSignature("createArtFromFactory(uint256)", artId)
        );

        // If not the factory, it must revert
The factory is not msg.sender (unless this contract is the factory, which it is not).
        assert(!successCreate);

        // State unchanged after failed factory call
        assert(c.owner() == ownerBefore);
        assert(c.tokenIdCounter() == tokenIdCounterBefore);

        // Try a factory-only claimFromFactory: should revert when not factory
        (bool successClaim, ) = address(c).call{value: 0}(
            abi.encodeWithSignature(
                "claimFromFactory(uint256,address,address,address,uint256,bytes32,string)",
                artId,
                to,
                address(0),
                address(0),
                quantity,
                dataHash,
                bytes(imageURI)
            )
        );

        // If msg.sender is not phiFactoryContract, must revert
        if (msg.sender != address(c.phiFactoryContract())) {
            assert(!successClaim);
        }

        // Try onlyPhiFactory: also must revert for non-factory
        (bool successUpdate, ) = address(c).call{value: 0}(
            abi.encodeWithSignature("updateRoyalties(uint256,(uint32,address))", tokenId, uint32(0), address(0))
        );

        // If caller is not owner/art creator, must revert
        address artist = address(0);
        {
            (bool ok, bytes memory ret) = address(c).call(
                abi.encodeWithSignature("getArtDataFromFactory(uint256)", artId)
            );
            if (ok && ret.length >= 32) {
                // ArtData struct: fields offset; artist is 4th? We don't rely on it; skip.
            }
        }

        // The only definitive check: owner-only pause must revert for non-owner
        (bool successPause, ) = address(c).call(abi.encodeWithSignature("pause()"));
        if (msg.sender != c.owner()) {
            assert(!successPause);
        }

        // Check that ownership/paused state didn't change unexpectedly
        assert(c.owner() == ownerBefore);
        assert(c.paused() == pausedBefore);

        // Core rule: any state changing call that reverts must not change c's observable state
        assert(c.tokenIdCounter() == tokenIdCounterBefore);
        assert(c.credId() == credIdBefore);
        assert(c.credChainId() == credChainIdBefore);
        assert(address(c.phiFactoryContract()) == phiFactoryBefore);
        assert(c.protocolFeeDestination() == protocolFeeBefore);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address caller,
        address from,
        address to,
        uint256 id,
        uint256 value
    ) public payable {
        require(from != address(0), "from zero");
        require(to != address(0), "to zero");
        require(caller != address(0), "caller zero");

        // Ensure the tokenId exists by minting? No, we cannot mint here. Use a random id; balance may be zero.
        // Rule still holds: revert if unauthorized, or exact transfer.
        uint256 senderBalanceBefore = c.balanceOf(from, id);
        uint256 receiverBalanceBefore = c.balanceOf(to, id);

        // Attempt transfer from `from` to `to` by `caller`
        // We use the public safeTransferFrom. If caller is not from and not approved, it must revert.
        bool reverted = false;
        try c.safeTransferFrom(from, to, id, value, "") {
            // success
        } catch {
            reverted = true;
        }

        bool authorized = (caller == from) || c.isApprovedForAll(from, caller);
        if (!authorized) {
            assert(reverted);
            assert(c.balanceOf(from, id) == senderBalanceBefore);
            assert(c.balanceOf(to, id) == receiverBalanceBefore);
        } else {
            if (!reverted) {
                assert(c.balanceOf(from, id) == senderBalanceBefore - value);
                assert(c.balanceOf(to, id) == receiverBalanceBefore + value);
            } else {
                // If it reverted, balances unchanged (e.g., insufficient balance or soulbound)
                assert(c.balanceOf(from, id) == senderBalanceBefore);
                assert(c.balanceOf(to, id) == receiverBalanceBefore);
            }
        }
    }
}

